    CONSTRAINT "devices_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "devices_type_check" CHECK ((type)::text = ANY ((ARRAY['Access Point'::character varying, 'Switch'::character varying, 'Router'::character varying, 'SmartPower'::character varying, 'CCTV'::character varying, 'NVR'::character varying])::text[])),
    CONSTRAINT "devices_addressing_mode_check" CHECK ((addressing_mode)::text = ANY ((ARRAY['Static'::character varying, 'DHCP'::character varying])::text[])),
    CONSTRAINT "devices_status_check" CHECK ((status)::text = ANY ((ARRAY['UP'::character varying, 'DOWN'::character varying])::text[]))
)
